import React, { useState } from "react";

const CompiladorView = () => {
    const [codigo, setCodigo] = useState("");
    const [resultado, setResultado] = useState("");

    const handleAnalisarCodigo = async () => {
        try {
          const response = await fetch("http://localhost:8080/api/compilar", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ codigo }),
          });
          const data = await response.json();
          setResultado(JSON.stringify(data, null, 2));
        } catch (error) {
          setResultado('Erro ao conectar com o compilador.');
        }
      };

    return (
        <div>
            <h1>Compilador Comida</h1>
            <textarea
                rows="10"
                cols="50"
                value={codigo}
                onChange={(e) => setCodigo(e.target.value)}
                placeholder="Digite o código aqui..."
            />
            <br />
            <button onClick={analisarCodigo}>Analisar Código</button>
            <h2>Resultado:</h2>
            <pre>{resultado}</pre>
        </div>
    );
};

export default CompiladorView;
